bool DownloadStatusUpdaterStubDispatch::Accept(
    DownloadStatusUpdater* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kDownloadStatusUpdater_BindClient_Name: {

      DCHECK(message->is_serialized());
      internal::DownloadStatusUpdater_BindClient_Params_Data* params =
          reinterpret_cast<internal::DownloadStatusUpdater_BindClient_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      ::mojo::PendingRemote<DownloadStatusUpdaterClient> p_client{};
      DownloadStatusUpdater_BindClient_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_client =
            input_data_view.TakeClient<decltype(p_client)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DownloadStatusUpdater::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->BindClient(
std::move(p_client));
      return true;
    }
    case internal::kDownloadStatusUpdater_Update_Name: {

      DCHECK(message->is_serialized());
      internal::DownloadStatusUpdater_Update_Params_Data* params =
          reinterpret_cast<internal::DownloadStatusUpdater_Update_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      DownloadStatusPtr p_status{};
      DownloadStatusUpdater_Update_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadStatus(&p_status))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DownloadStatusUpdater::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Update(
std::move(p_status));
      return true;
    }
  }
  return false;
}

